// --- Transport ---

/** Per-operation transport options. The generator threads these straight
 * through to `Transport.request` without inspecting them, so concrete
 * transports can layer in framework-specific knobs (e.g. axios's
 * `skipErrorPopup`) without the codegen having to know about them.
 */
export interface TransportOptions {
  [key: string]: unknown
}

export interface TransportRequest {
  /** Stable identifier for the operation issuing this request, of the form
   * `<ServiceClient>.<methodName>`. Middleware (e.g. tracing) can use this
   * to name a span or attach attributes; the underlying HTTP transport
   * ignores it.
   */
  operation: string
  method: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE'
  url: string
  /** A list value is sent as the parameter repeated, once per element. */
  query?: Record<string, string | number | boolean | readonly string[] | undefined>
  headers?: Record<string, string>
  body?: unknown
  options?: TransportOptions
}

export interface TransportResponse {
  status: number
  body: unknown
  /** Lowercased header names → values. Concrete transports must lowercase
   * keys so the client's error-dispatch lookup is case-insensitive.
   */
  headers: Record<string, string>
}

export interface Transport {
  request(req: TransportRequest): Promise<TransportResponse>
}

/** Thrown when the server returned a non-2xx status the client couldn't
 * match against the operation's declared errors — either no error is
 * declared for that status, or `X-Error-Type` didn't name any of them.
 * 401s are converted to `UnauthenticatedError` by the transport before
 * the client sees them, so they don't surface here.
 */
export class UnexpectedResponseError extends Error {
  readonly operation: string
  readonly status: number
  readonly body: unknown
  readonly headers: Record<string, string>
  constructor(operation: string, status: number, body: unknown, headers: Record<string, string>) {
    super(operation + ' -> ' + status)
    this.name = 'UnexpectedResponseError'
    this.operation = operation
    this.status = status
    this.body = body
    this.headers = headers
  }
}

/** Thrown by the transport for any 401. The auth middleware sits in front
 * of every route and isn't modelled per-operation, so 401 is never in an
 * operation's `errors: [...]` — we surface it as a typed error here.
 */
export class UnauthenticatedError extends Error {
  readonly operation: string
  constructor(operation: string) {
    super(operation + ' -> 401 Unauthorized')
    this.name = 'UnauthenticatedError'
    this.operation = operation
  }
}

/** A request whose body is streamed, whose response body is streamed,
 * or both. Everything a `TransportRequest` carries applies here too;
 * what is added is the framing and the outgoing stream.
 *
 * `streamEncoding` tells the transport how to frame each direction that
 * streams — the generator derives it from the shape of the `@streaming`
 * member, so the transport never has to guess from a content type:
 *
 *   - `'ndjson'` — one JSON value per line (`application/x-ndjson`).
 *     Outgoing: `JSON.stringify` each element, terminate each with a
 *     newline. Incoming: split on newlines, skip blank lines, and
 *     `JSON.parse` each one. The generated client applies the element
 *     schema on top of whatever is yielded here.
 *   - `'sse'` — one server-sent event per JSON value
 *     (`text/event-stream`), for a union marked `@serverSentEvents`.
 *     Outgoing: each element's JSON as an event's `data`, then the
 *     terminator event if `requestStreamTerminator` is set. Incoming:
 *     `JSON.parse` each event's `data`, skipping comments, other fields,
 *     keep-alives and the `responseStreamTerminator` event.
 *   - `'binary'` — the body verbatim
 *     (`application/octet-stream`), as `Uint8Array` chunks. Chunk
 *     boundaries carry no meaning in either direction.
 */
export type StreamEncoding = 'ndjson' | 'sse' | 'binary'

export interface StreamTransportRequest extends TransportRequest {
  /** Framing for the request body, when it streams. `undefined` means the
   * request body is an ordinary (unary) JSON body carried by `body`.
   */
  requestStreamEncoding?: StreamEncoding
  /** Framing the response body is expected in, when it streams.
   * `undefined` means an ordinary JSON response body.
   */
  responseStreamEncoding?: StreamEncoding
  /** For an `'sse'` request: the data of one more event to send after
   * the last value (the union's `@serverSentEvents(terminator:)`).
   */
  requestStreamTerminator?: string
  /** For an `'sse'` response: the data of the event the server sends
   * after the last value, which is not itself a value and is skipped.
   */
  responseStreamTerminator?: string
  /** The outgoing stream, present exactly when `requestStreamEncoding` is.
   * For `'ndjson'` and `'sse'` these are the values to serialise; for
   * `'binary'`, `Uint8Array` chunks. Overrides `body`.
   */
  stream?: AsyncIterable<unknown>
}

export interface StreamTransportResponse {
  status: number
  /** Lowercased header names → values, as on `TransportResponse`. */
  headers: Record<string, string>
  /** The deframed response body, present exactly when the operation
   * streams its output and the status was 2xx. Elements are the values
   * `responseStreamEncoding` describes — already `JSON.parse`d for
   * `'ndjson'` and `'sse'`, raw `Uint8Array` chunks for `'binary'`. The
   * generated client validates those elements against the operation's
   * schema.
   */
  stream?: AsyncIterable<unknown>
  /** The fully-read body, for a non-2xx response (so declared errors can
   * be parsed and thrown) or an operation with a unary response body.
   */
  body?: unknown
}

/** The streaming counterpart of `Transport`. A transport that backs a
 * service with streaming operations implements both; the generated client
 * takes whichever it needs.
 *
 * A streamed response commits its HTTP status before the first element is
 * pulled, so a failure that happens mid-stream cannot arrive as a status.
 * Such failures are modelled as members of the streamed union instead —
 * the protocol expects a terminal member (e.g. `completed` / `failed`) —
 * so `requestStream` rejecting means the request failed *before* the
 * stream started, and an error after that surfaces as an element or as an
 * exception thrown while iterating.
 */
export interface StreamTransport {
  requestStream(req: StreamTransportRequest): Promise<StreamTransportResponse>
}

/** Thrown when a streamed response was expected but the transport didn't
 * produce one (a transport bug, or a server that answered 2xx with a
 * non-streamed body). */
export class MissingStreamError extends Error {
  readonly operation: string
  constructor(operation: string) {
    super(operation + ' -> response did not carry a stream')
    this.name = 'MissingStreamError'
    this.operation = operation
  }
}

/** Validates each element of a deframed ndjson stream against the
 * operation's element schema, lazily — an element is parsed as it is
 * pulled, so a long-running stream doesn't buffer and a malformed element
 * fails at that element rather than silently truncating the stream. */
export const decodeStream = async function* <T>(
  source: AsyncIterable<unknown>,
  schema: { parse: (value: unknown) => T },
  operation: string,
): AsyncGenerator<T, void, undefined> {
  for await (const element of source) {
    try {
      yield schema.parse(element)
    } catch (err) {
      throw new StreamDecodeError(operation, element, err)
    }
  }
}

/** Applies `f` to each element of a stream as it is pulled. */
const wireMapStream = async function* <A, B>(
  source: AsyncIterable<A>,
  f: (element: A) => B,
): AsyncGenerator<B, void, undefined> {
  for await (const element of source) yield f(element)
}

/** An empty stream, used when a request that declares a streamed input
 * arrives without one (e.g. a mock invoked with no stream). */
export const emptyStream = async function* (): AsyncGenerator<never, void, undefined> {}

/** Thrown while iterating a streamed response whose element failed the
 * operation's schema. Carries the offending element so a caller can log
 * what actually came over the wire. */
export class StreamDecodeError extends Error {
  readonly operation: string
  readonly element: unknown
  constructor(operation: string, element: unknown, cause: unknown) {
    super(operation + ' -> could not decode a stream element', { cause })
    this.name = 'StreamDecodeError'
    this.operation = operation
    this.element = element
  }
}


