export class FeedClient {
  private readonly transport: Transport
  private readonly streamTransport: StreamTransport
  constructor(transport: Transport, streamTransport: StreamTransport) {
    this.transport = transport
    this.streamTransport = streamTransport
  }

  /**
   * Streams ndjson in both directions.
   * Streams `incoming` to the server as newline-delimited `FeedEvent` values.
   * Resolves once the response status is known; `outgoing` then yields newline-delimited `FeedEvent` values lazily, so iterate it to consume the response.
   */
  async echo(input: EchoInput, opts?: TransportOptions): Promise<EchoOutput> {
    const url = `/echo`
    const res = await this.streamTransport.requestStream({
      operation: 'FeedClient.echo',
      method: 'POST',
      url,
      body: undefined,
      requestStreamEncoding: 'ndjson',
      stream: wireMapStream(input.incoming, encodeFeedEvent),
      responseStreamEncoding: 'ndjson',
      options: opts,
    })
    if (res.status >= 200 && res.status < 300) {
      if (res.stream === undefined) {
        throw new MissingStreamError('FeedClient.echo')
      }
      const raw: Record<string, unknown> = {}
      raw['outgoing'] = decodeStream(res.stream, { parse: (value: unknown) => FeedEventSchema.parse(decodeFeedEvent(value)) }, 'FeedClient.echo')
      return raw as EchoOutput
    }
    if (res.status === 404) {
      throw new NotFoundError(decodeNotFoundResponse(res))
    }
    throw new UnexpectedResponseError('FeedClient.echo', res.status, res.body, res.headers)
  }

  /**
   * Streams server-sent events out, closed by a terminator event.
   * Resolves once the response status is known; `notifications` then yields `Notification` values as server-sent events lazily, so iterate it to consume the response.
   */
  async notify(input: NotifyInput, opts?: TransportOptions): Promise<NotifyOutput> {
    const url = `/notify`
    const res = await this.streamTransport.requestStream({
      operation: 'FeedClient.notify',
      method: 'POST',
      url,
      body: { 'topic': input.topic ?? undefined },
      responseStreamEncoding: 'sse',
      responseStreamTerminator: '[DONE]',
      options: opts,
    })
    if (res.status >= 200 && res.status < 300) {
      if (res.stream === undefined) {
        throw new MissingStreamError('FeedClient.notify')
      }
      const raw: Record<string, unknown> = {}
      raw['notifications'] = decodeStream(res.stream, { parse: (value: unknown) => NotificationSchema.parse(decodeNotification(value)) }, 'FeedClient.notify')
      return raw as NotifyOutput
    }
    if (res.status === 404) {
      throw new NotFoundError(decodeNotFoundResponse(res))
    }
    throw new UnexpectedResponseError('FeedClient.notify', res.status, res.body, res.headers)
  }

  /** A unary operation on a streaming service. */
  async plain(opts?: TransportOptions): Promise<PlainOutput> {
    const url = `/plain`
    const res = await this.transport.request({
      operation: 'FeedClient.plain',
      method: 'GET',
      url,
      body: undefined,
      options: opts,
    })
    if (res.status >= 200 && res.status < 300) {
      return decodePlainOutputResponse(res)
    }
    if (res.status === 404) {
      throw new NotFoundError(decodeNotFoundResponse(res))
    }
    throw new UnexpectedResponseError('FeedClient.plain', res.status, res.body, res.headers)
  }

  /**
   * Streams server-sent events in, with no terminator.
   * Streams `entries` to the server as `ReportEntry` values as server-sent events.
   */
  async report(input: ReportInput, opts?: TransportOptions): Promise<ReportOutput> {
    const url = `/report`
    const res = await this.streamTransport.requestStream({
      operation: 'FeedClient.report',
      method: 'POST',
      url,
      body: undefined,
      requestStreamEncoding: 'sse',
      stream: wireMapStream(input.entries, encodeReportEntry),
      options: opts,
    })
    if (res.status >= 200 && res.status < 300) {
      return decodeReportOutputResponse(res)
    }
    if (res.status === 404) {
      throw new NotFoundError(decodeNotFoundResponse(res))
    }
    throw new UnexpectedResponseError('FeedClient.report', res.status, res.body, res.headers)
  }

  /**
   * Streams raw bytes in.
   * Streams `body` to the server as raw bytes.
   */
  async upload(input: UploadInput, opts?: TransportOptions): Promise<UploadOutput> {
    const url = `/upload/${wireEncodeLabel(String(input.id))}`
    const res = await this.streamTransport.requestStream({
      operation: 'FeedClient.upload',
      method: 'POST',
      url,
      body: undefined,
      requestStreamEncoding: 'binary',
      stream: input.body,
      options: opts,
    })
    if (res.status >= 200 && res.status < 300) {
      return decodeUploadOutputResponse(res)
    }
    if (res.status === 404) {
      throw new NotFoundError(decodeNotFoundResponse(res))
    }
    throw new UnexpectedResponseError('FeedClient.upload', res.status, res.body, res.headers)
  }

  /**
   * Streams ndjson out, with a header alongside the stream.
   * Resolves once the response status is known; `events` then yields newline-delimited `FeedEvent` values lazily, so iterate it to consume the response.
   */
  async watch(input: WatchInput, opts?: TransportOptions): Promise<WatchOutput> {
    const url = `/watch/${wireEncodeLabel(String(input.id))}`
    const query: Record<string, string | readonly string[] | undefined> = {}
    if (input.since !== undefined) query['since'] = wireDateTime(input.since)
    const res = await this.streamTransport.requestStream({
      operation: 'FeedClient.watch',
      method: 'GET',
      url,
      query,
      body: undefined,
      responseStreamEncoding: 'ndjson',
      options: opts,
    })
    if (res.status >= 200 && res.status < 300) {
      if (res.stream === undefined) {
        throw new MissingStreamError('FeedClient.watch')
      }
      const raw: Record<string, unknown> = {}
      if (res.headers['x-session'] !== undefined) {
        raw['session'] = z.string().parse(res.headers['x-session'])
      }
      raw['events'] = decodeStream(res.stream, { parse: (value: unknown) => FeedEventSchema.parse(decodeFeedEvent(value)) }, 'FeedClient.watch')
      return raw as WatchOutput
    }
    if (res.status === 404) {
      throw new NotFoundError(decodeNotFoundResponse(res))
    }
    throw new UnexpectedResponseError('FeedClient.watch', res.status, res.body, res.headers)
  }
}


// --- Storybook mock server ---

/** A request as seen by the mock server: the URL path already has any
 * proxy prefix stripped, `pathParams` holds decoded `@httpLabel`
 * values, `query` the parsed query string, `body` the parsed JSON body. */
export interface MockRequest {
  method: string
  path: string
  pathParams: Record<string, string>
  query: Record<string, string | undefined>
  body: unknown
  /** The deframed request body, for an operation that streams its input.
   * Elements are `JSON.parse`d values for an ndjson or sse stream and
   * `Uint8Array` chunks for a binary one — the same shape the streaming
   * transport yields, so a mock and a real server see the same thing. */
  stream?: AsyncIterable<unknown>
}

export interface MockResponse {
  status: number
  body: unknown
  headers: Record<string, string>
  /** Set instead of `body` when the operation streams its output; the
   * adapter frames these elements per `streamEncoding`. */
  stream?: AsyncIterable<unknown>
  /** Framing for `stream`, mirroring `StreamEncoding` on the transport. */
  streamEncoding?: 'ndjson' | 'sse' | 'binary'
  /** For an `'sse'` stream: the data of the event to send after the last
   * element, if the union declares one. */
  streamTerminator?: string
}

/** One URI path segment of an operation's route: a literal or a
 * `@httpLabel` capture. */
export type MockUriSegment = { readonly literal: string } | { readonly label: string }

/** A single operation's route + codecs. `decodeInput` turns a matched
 * request into the operation's typed input; `encodeBody` extracts the
 * HTTP response body from the typed output. */
export interface MockOperation<Handlers> {
  readonly key: keyof Handlers & string
  readonly method: string
  readonly segments: readonly MockUriSegment[]
  readonly decodeInput: (req: MockRequest) => unknown
  readonly encodeBody: (output: unknown) => unknown
  /** Framing of this operation's streamed output, when it streams one.
   * `undefined` for an ordinary unary operation. */
  readonly responseStreamEncoding?: 'ndjson' | 'sse' | 'binary'
  /** The terminator event's data, for an `'sse'` output that declares one. */
  readonly responseStreamTerminator?: string
  /** Pulls the streamed member out of a handler's returned output, for
   * an operation that streams its output. */
  readonly encodeStream?: (output: unknown) => AsyncIterable<unknown>
}

export interface MockServiceDescriptor<Handlers> {
  readonly serviceName: string
  readonly operations: readonly MockOperation<Handlers>[]
}

/** Thrown from a handler to return an arbitrary HTTP status/body that
 * isn't one of the operation's declared, typed errors (e.g. a 503 to
 * exercise a generic failure path). */
export class MockHttpError extends Error {
  readonly status: number
  readonly body: unknown
  constructor(status: number, body: unknown = { message: 'Error' }) {
    super('MockHttpError ' + status)
    this.name = 'MockHttpError'
    this.status = status
    this.body = body
  }
}

/** A matched, ready-to-run mock operation: everything the shared adapter
 * needs to invoke one handler and encode its result. */
export interface MockMatch {
  run: (req: MockRequest) => Promise<MockResponse>
}

/** A bound service mock: a matcher from HTTP method + path to a runnable
 * operation, or `null` when this service handles no such route. */
export interface BoundMockService {
  serviceName: string
  match: (method: string, path: string) => MockMatch | null
}

const matchSegments = (
  segments: readonly MockUriSegment[],
  path: string,
): Record<string, string> | null => {
  const parts = path.split('/').filter((p) => p.length > 0)
  if (parts.length !== segments.length) return null
  const pathParams: Record<string, string> = {}
  for (let i = 0; i < segments.length; i++) {
    const seg = segments[i]
    if ('literal' in seg) {
      if (seg.literal !== parts[i]) return null
    }
    else {
      pathParams[seg.label] = decodeURIComponent(parts[i])
    }
  }
  return pathParams
}

/** Binds a service descriptor to a partial set of handlers, producing a
 * matcher. An unimplemented operation that gets called throws, so stories
 * only implement the operations they exercise. A thrown generated error
 * (`XxxError`) is encoded to its declared status + `x-error-type`; a
 * `MockHttpError` to its status/body; anything else re-throws. */
export const mockService = <Handlers>(
  descriptor: MockServiceDescriptor<Handlers>,
  handlers: Partial<Handlers>,
): BoundMockService => ({
  serviceName: descriptor.serviceName,
  match: (method, path) => {
    for (const op of descriptor.operations) {
      if (op.method !== method) continue
      const pathParams = matchSegments(op.segments, path)
      if (pathParams === null) continue
      const handler = handlers[op.key] as
        | ((input: unknown) => unknown | Promise<unknown>)
        | undefined
      return {
        run: async (req): Promise<MockResponse> => {
          if (handler === undefined) {
            throw new Error(descriptor.serviceName + '.' + op.key + ' called but no mock handler was provided')
          }
          const input = op.decodeInput({ ...req, pathParams })
          try {
            const output = await handler(input)
            if (op.encodeStream !== undefined) {
              return {
                status: 200,
                body: op.encodeBody(output),
                headers: {},
                stream: op.encodeStream(output),
                streamEncoding: op.responseStreamEncoding,
                ...(op.responseStreamTerminator !== undefined ? { streamTerminator: op.responseStreamTerminator } : {}),
              }
            }
            return { status: 200, body: op.encodeBody(output), headers: {} }
          } catch (err) {
            if (err instanceof MockHttpError) {
              return { status: err.status, body: err.body, headers: {} }
            }
            if (isTypedMockError(err)) {
              return { status: err.status, body: err.payload, headers: { 'x-error-type': err.errorType } }
            }
            throw err
          }
        },
      }
    }
    return null
  },
})

interface TypedMockError {
  status: number
  errorType: string
  payload: unknown
}

const isTypedMockError = (err: unknown): err is TypedMockError =>
  err instanceof Error &&
  typeof (err as { status?: unknown }).status === 'number' &&
  typeof (err as { errorType?: unknown }).errorType === 'string' &&
  'payload' in err

/** Routes a request across several bound services, returning the first
 * match. Stories pass the mocks for whichever services a screen touches. */
export const mockServices = (
  ...services: readonly BoundMockService[]
): ((method: string, path: string) => MockMatch | null) =>
  (method, path) => {
    for (const svc of services) {
      const m = svc.match(method, path)
      if (m !== null) return m
    }
    return null
  }

